-- ==== 20260924002500_assignment_changes_replan.sql
-- When assignments change, keep study blocks valid immediately and replan soon after.
--
-- In the same transaction as the edit:
--   * due date moved earlier: planned blocks for it that now end after the new due time
--     are deleted (a block must never sit past its deadline, even briefly)
--   * marked done/skipped: its future planned blocks are deleted (the time is freed)
-- Then the user is queued for a replan; pg_cron drains the queue every minute into the
-- nightly-replan function, so a burst of edits becomes one replan.

create table public.replan_requests (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  requested_at timestamptz not null default now(),
  reason text
);

alter table public.replan_requests enable row level security;
-- No policies: internal queue, service role only.
revoke all on public.replan_requests from anon, authenticated;

create or replace function private.request_replan(p_user_id uuid, p_reason text)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.replan_requests (user_id, requested_at, reason)
  values (p_user_id, now(), p_reason)
  on conflict (user_id) do update set requested_at = excluded.requested_at, reason = excluded.reason;
$$;

create or replace function private.on_assignment_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid;
begin
  select c.user_id into v_user_id
  from public.courses c
  where c.id = coalesce(new.course_id, old.course_id);
  if v_user_id is null then
    return null;
  end if;

  if tg_op = 'DELETE' then
    perform private.request_replan(v_user_id, 'assignment_deleted');
    return null;
  end if;

  if tg_op = 'UPDATE' then
    if new.status in ('done', 'skipped') and old.status not in ('done', 'skipped') then
      delete from public.study_blocks
      where assignment_id = new.id and status = 'planned' and starts_at > now();
    end if;
    if new.due_at is distinct from old.due_at and new.due_at is not null then
      delete from public.study_blocks
      where assignment_id = new.id and status = 'planned' and ends_at > new.due_at;
    end if;
    -- Only changes that affect planning trigger a replan.
    if new.due_at is not distinct from old.due_at
       and new.status is not distinct from old.status
       and new.estimated_minutes is not distinct from old.estimated_minutes
       and new.kind is not distinct from old.kind
       and new.category_id is not distinct from old.category_id
       and new.points_possible is not distinct from old.points_possible then
      return null;
    end if;
  end if;

  perform private.request_replan(v_user_id, lower(tg_op) || '_assignment');
  return null;
end;
$$;

create trigger assignments_replan
after insert or update or delete on public.assignments
for each row execute function private.on_assignment_change();

-- Drains up to 200 queued users into one nightly-replan call (which also marks missed
-- blocks). Requests younger than 20 seconds wait for the next run, so a user editing
-- several assignments in a row gets a single replan.
create or replace function private.process_replan_requests()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ids uuid[];
begin
  with picked as (
    select user_id from public.replan_requests
    where requested_at < now() - interval '20 seconds'
    order by requested_at
    limit 200
    for update skip locked
  ),
  deleted as (
    delete from public.replan_requests r using picked where r.user_id = picked.user_id
    returning r.user_id
  )
  select array_agg(user_id) into v_ids from deleted;

  if v_ids is null or cardinality(v_ids) = 0 then
    return 0;
  end if;
  perform private.invoke_edge_function('nightly-replan', jsonb_build_object('user_ids', to_jsonb(v_ids)));
  return cardinality(v_ids);
end;
$$;

revoke execute on function private.request_replan(uuid, text) from public, anon, authenticated;
revoke execute on function private.on_assignment_change() from public, anon, authenticated;
revoke execute on function private.process_replan_requests() from public, anon, authenticated;

select cron.schedule('process-replan-requests', '* * * * *', $$ select private.process_replan_requests() $$);

-- ==== 20260924002600_calendar_feed.sql
-- Per-user ICS calendar feed behind a secret URL. Only a SHA-256 hash of the token is
-- stored; the token itself is shown once when created. Rotating replaces the old URL.
alter table public.profiles
  add column calendar_token_hash text unique
    constraint profiles_calendar_token_hash_format check (calendar_token_hash ~ '^[0-9a-f]{64}$');

-- Creates (or replaces) the caller's feed token and returns it. The old URL stops working.
create or replace function public.rotate_calendar_token()
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_token text;
begin
  if v_user_id is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- 32 random bytes, URL-safe base64 without padding.
  v_token := rtrim(translate(encode(extensions.gen_random_bytes(32), 'base64'), '+/', '-_'), '=');
  update public.profiles
  set calendar_token_hash = encode(extensions.digest(v_token, 'sha256'), 'hex')
  where id = v_user_id;
  return v_token;
end;
$$;

-- Turns the feed off.
create or replace function public.revoke_calendar_token()
returns void
language sql
security definer
set search_path = ''
as $$
  update public.profiles set calendar_token_hash = null where id = (select auth.uid());
$$;

revoke execute on function public.rotate_calendar_token() from public, anon;
revoke execute on function public.revoke_calendar_token() from public, anon;
grant execute on function public.rotate_calendar_token() to authenticated;
grant execute on function public.revoke_calendar_token() to authenticated;

-- ==== 20260924002700_push_tokens.sql
-- Push token registration, refresh, and cleanup.

-- Registers (or refreshes) a device's push token for the caller. A token is unique per
-- provider, so if the device was signed into another account the token moves here.
-- When the same device reports a new token (Expo/FCM/APNs rotate them), the device's
-- older tokens are retired. Registering also revives a token previously marked invalid.
create or replace function public.register_push_token(
  p_provider public.push_provider,
  p_token text,
  p_platform text,
  p_device_id text default null,
  p_app_version text default null,
  p_web_push_keys jsonb default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_id uuid;
begin
  if v_user_id is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_provider = 'expo' and p_token !~ '^(Exponent|Expo)PushToken\[[A-Za-z0-9_-]+\]$' then
    raise exception 'not an Expo push token' using errcode = '22023';
  end if;

  insert into public.notification_tokens (user_id, provider, token, platform, device_id, app_version, web_push_keys, last_seen_at, invalidated_at)
  values (v_user_id, p_provider, p_token, p_platform, p_device_id, p_app_version, p_web_push_keys, now(), null)
  on conflict (provider, token) do update
    set user_id = excluded.user_id,
        platform = excluded.platform,
        device_id = coalesce(excluded.device_id, public.notification_tokens.device_id),
        app_version = coalesce(excluded.app_version, public.notification_tokens.app_version),
        web_push_keys = coalesce(excluded.web_push_keys, public.notification_tokens.web_push_keys),
        last_seen_at = now(),
        invalidated_at = null
  returning id into v_id;

  -- Token refresh: older tokens from the same device are no longer valid.
  if p_device_id is not null then
    update public.notification_tokens
    set invalidated_at = now()
    where user_id = v_user_id and device_id = p_device_id and provider = p_provider
      and id <> v_id and invalidated_at is null;
  end if;

  return v_id;
end;
$$;

-- Removes a token (sign-out on a device).
create or replace function public.unregister_push_token(p_provider public.push_provider, p_token text)
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.notification_tokens
  where provider = p_provider and token = p_token and user_id = (select auth.uid());
$$;

-- Marks tokens the provider reported as dead (service role; used by senders).
create or replace function public.invalidate_push_tokens(p_token_ids uuid[])
returns integer
language sql
security definer
set search_path = ''
as $$
  with updated as (
    update public.notification_tokens set invalidated_at = now()
    where id = any (p_token_ids) and invalidated_at is null
    returning 1
  )
  select count(*)::integer from updated;
$$;

-- Daily cleanup: tokens invalid for a week, or not seen for 90 days (app uninstalled
-- or never opened again), are deleted.
create or replace function private.cleanup_push_tokens()
returns integer
language sql
security definer
set search_path = ''
as $$
  with deleted as (
    delete from public.notification_tokens
    where invalidated_at < now() - interval '7 days'
       or last_seen_at < now() - interval '90 days'
    returning 1
  )
  select count(*)::integer from deleted;
$$;

revoke execute on function public.register_push_token(public.push_provider, text, text, text, text, jsonb) from public, anon;
revoke execute on function public.unregister_push_token(public.push_provider, text) from public, anon;
revoke execute on function public.invalidate_push_tokens(uuid[]) from public, anon, authenticated;
revoke execute on function private.cleanup_push_tokens() from public, anon, authenticated;
grant execute on function public.register_push_token(public.push_provider, text, text, text, text, jsonb) to authenticated;
grant execute on function public.unregister_push_token(public.push_provider, text) to authenticated;
grant execute on function public.invalidate_push_tokens(uuid[]) to service_role;

select cron.schedule('cleanup-push-tokens', '17 4 * * *', $$ select private.cleanup_push_tokens() $$);

