-- ==== 20260924002900_notification_caps.sql
-- Daily cap and repeat suppression for reminders, enforced where reminders are claimed.
--
-- claim_reminders now receives the planned reminders (most urgent first) and, holding a
-- per-user lock so overlapping cron runs can't both pass the checks, claims each one
-- unless:
-- - its key was already claimed (exact dedupe, as before)
-- - it is about an assignment that got a reminder in the last 6 hours (cooldown). This
--   stops "exam in 1 day" at 07:30 followed by "due in 24 hours" an hour later. The
--   2-hour reminder is exempt: it is the last nudge before the deadline.
-- - the user already got daily_cap reminders today (local day in their timezone).
-- Cooldown-suppressed reminders are recorded as suppressed so they are never retried;
-- cap-skipped ones are not recorded, so they can still go out after the day rolls over
-- if still relevant. Suppressed rows don't count toward the cap.

alter table public.notification_dedupe
  add column assignment_id uuid,
  add column kind text,
  add column suppressed boolean not null default false;

create index notification_dedupe_user_created_idx on public.notification_dedupe (user_id, created_at);

drop function public.claim_reminders(uuid, text[]);

create function public.claim_reminders(
  p_user_id uuid,
  p_timezone text,
  p_daily_cap integer,
  p_reminders jsonb
)
returns text[]
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_day_start timestamptz := date_trunc('day', now() at time zone p_timezone) at time zone p_timezone;
  v_sent_today integer;
  v_claimed text[] := '{}'::text[];
  r record;
begin
  if jsonb_typeof(p_reminders) is distinct from 'array' then
    raise exception 'p_reminders must be a JSON array' using errcode = '22023';
  end if;

  -- Serialize claims per user.
  perform pg_advisory_xact_lock(hashtextextended('claim_reminders:' || p_user_id::text, 0));

  select count(*) into v_sent_today
  from public.notification_dedupe d
  where d.user_id = p_user_id and not d.suppressed and d.created_at >= v_day_start;

  for r in
    select e.value ->> 'key' as key, e.value ->> 'kind' as kind,
           nullif(e.value ->> 'assignmentId', '')::uuid as assignment_id
    from jsonb_array_elements(p_reminders) with ordinality as e (value, i)
    order by e.i
  loop
    continue when r.key is null
      or exists (select 1 from public.notification_dedupe d where d.user_id = p_user_id and d.dedupe_key = r.key);

    if r.assignment_id is not null and r.kind is distinct from 'due_2h' and exists (
      select 1 from public.notification_dedupe d
      where d.user_id = p_user_id and d.assignment_id = r.assignment_id
        and not d.suppressed and d.created_at > now() - interval '6 hours'
    ) then
      insert into public.notification_dedupe (user_id, dedupe_key, assignment_id, kind, suppressed)
      values (p_user_id, r.key, r.assignment_id, r.kind, true);
      continue;
    end if;

    exit when v_sent_today >= p_daily_cap;

    insert into public.notification_dedupe (user_id, dedupe_key, assignment_id, kind)
    values (p_user_id, r.key, r.assignment_id, r.kind);
    v_sent_today := v_sent_today + 1;
    v_claimed := v_claimed || r.key;
  end loop;

  return v_claimed;
end;
$$;

revoke execute on function public.claim_reminders(uuid, text, integer, jsonb) from public, anon, authenticated;
grant execute on function public.claim_reminders(uuid, text, integer, jsonb) to service_role;

-- ==== 20260924003000_email_digest.sql
-- Daily email digest (Resend) for users push doesn't reach: push turned off, or no
-- active device. Sent by the send-email-digests cron function at the user's digest time.

-- On by default: it only goes to users without push, and every email has a one-click
-- unsubscribe link (email-unsubscribe function) that turns this off.
alter table public.notification_prefs alter column email_digest_enabled set default true;

-- Users due a digest right now: opted in, confirmed email, push not reaching them,
-- local time within 3 hours after their digest time, and not yet sent today.
-- Includes open assignments due in the next 8 days. Paged by user id. Service role only.
create or replace function public.email_digest_batch(p_now timestamptz, p_after uuid default null, p_limit integer default 500)
returns table (user_id uuid, email text, display_name text, timezone text, digest_time text, assignments jsonb)
language sql
stable
security definer
set search_path = ''
as $$
  select
    p.id,
    u.email::text,
    p.display_name,
    p.timezone,
    to_char(np.morning_digest_time, 'HH24:MI'),
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', a.id, 'title', a.title, 'course', coalesce(c.code, c.name), 'kind', a.kind,
        'dueAt', to_char(a.due_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'), 'status', a.status
      ) order by a.due_at)
      from public.assignments a
      join public.courses c on c.id = a.course_id
      where c.user_id = p.id and c.archived_at is null
        and a.status in ('todo', 'in_progress')
        and a.due_at > p_now and a.due_at <= p_now + interval '8 days'
    ), '[]'::jsonb)
  from public.profiles p
  join auth.users u on u.id = p.id
  join public.notification_prefs np on np.user_id = p.id
  cross join lateral (select (p_now at time zone p.timezone) as local_now) l
  where np.email_digest_enabled
    and u.email is not null
    and u.email_confirmed_at is not null
    and not (
      np.push_enabled and exists (
        select 1 from public.notification_tokens t where t.user_id = p.id and t.invalidated_at is null
      )
    )
    -- time - time is a signed interval, so this never wraps past midnight (a late
    -- digest time sends until midnight at the latest, as in planEmailDigest).
    and l.local_now::time - np.morning_digest_time between interval '0' and interval '3 hours'
    and not exists (
      select 1 from public.notification_dedupe d
      where d.user_id = p.id and d.dedupe_key = 'email_digest:' || to_char(l.local_now::date, 'YYYY-MM-DD')
    )
    and (p_after is null or p.id > p_after)
  order by p.id
  limit p_limit;
$$;

revoke execute on function public.email_digest_batch(timestamptz, uuid, integer) from public, anon, authenticated;
grant execute on function public.email_digest_batch(timestamptz, uuid, integer) to service_role;

-- One-click unsubscribe (service role; the function verifies the signed link first).
create or replace function public.unsubscribe_email_digest(p_user_id uuid)
returns boolean
language sql
security definer
set search_path = ''
as $$
  with updated as (
    update public.notification_prefs set email_digest_enabled = false
    where user_id = p_user_id and email_digest_enabled
    returning 1
  )
  select exists (select 1 from public.notification_prefs where user_id = p_user_id);
$$;

revoke execute on function public.unsubscribe_email_digest(uuid) from public, anon, authenticated;
grant execute on function public.unsubscribe_email_digest(uuid) to service_role;

select cron.schedule('send-email-digests', '*/15 * * * *', $$ select private.invoke_edge_function('send-email-digests') $$);

-- ==== 20260924003100_billing_customers.sql
-- Maps users to their Stripe customer. Created on first checkout by the stripe-checkout
-- function (service role); webhooks use it to find the user for a customer.

create table public.billing_customers (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  stripe_customer_id text not null unique check (stripe_customer_id ~ '^cus_[A-Za-z0-9]+$'),
  created_at timestamptz not null default now()
);

alter table public.billing_customers enable row level security;
-- Internal: service role only (no policies, no client privileges).
revoke all on public.billing_customers from anon, authenticated;

-- ==== 20260924003200_billing_events.sql
-- Billing webhook processing: an event ledger for idempotency, and one function that
-- records an event and applies its subscription change atomically.
--
-- - Idempotent on event id: a redelivered event finds its ledger row and does nothing.
-- - Ordered: a subscription row only changes if the event is not older than the one that
--   last wrote it (provider_updated_at), so out-of-order deliveries can't roll back state.
-- - The cached profiles.plan_tier is recomputed from subscriptions after each change.

create table public.billing_events (
  provider public.billing_provider not null,
  event_id text not null check (char_length(event_id) between 1 and 255),
  event_type text not null,
  event_created_at timestamptz not null,
  -- Cascades with account deletion; later redeliveries then resolve to unknown_user.
  user_id uuid references public.profiles (id) on delete cascade,
  -- applied | ignored | stale | unknown_user
  result text,
  received_at timestamptz not null default now(),
  primary key (provider, event_id)
);

alter table public.billing_events enable row level security;
revoke all on public.billing_events from anon, authenticated;

-- Pro while any subscription is in a state that grants access.
create or replace function private.refresh_plan_tier(p_user_id uuid)
returns public.plan_tier
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tier public.plan_tier;
begin
  v_tier := case when exists (
    select 1 from public.subscriptions s
    where s.user_id = p_user_id and s.status in ('trialing', 'active', 'past_due', 'in_grace')
  ) then 'pro' else 'free' end;
  update public.profiles set plan_tier = v_tier where id = p_user_id and plan_tier is distinct from v_tier;
  return v_tier;
end;
$$;
revoke execute on function private.refresh_plan_tier(uuid) from public, anon, authenticated;

-- p_subscription (null for events that change nothing): {
--   provider_subscription_id, provider_customer_id, user_id?, product_id, status,
--   current_period_end, cancel_at_period_end, canceled_at, grace_period_ends_at? }
-- Returns applied | duplicate | ignored | stale | unknown_user.
create or replace function public.apply_billing_event(
  p_provider public.billing_provider,
  p_event_id text,
  p_event_type text,
  p_event_created_at timestamptz,
  p_subscription jsonb default null
)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sub_id text := p_subscription ->> 'provider_subscription_id';
  v_customer text := p_subscription ->> 'provider_customer_id';
  v_claimed_user uuid;
  v_user uuid;
  v_changed boolean;
  v_result text;
begin
  insert into public.billing_events (provider, event_id, event_type, event_created_at)
  values (p_provider, p_event_id, p_event_type, p_event_created_at)
  on conflict do nothing;
  if not found then
    return 'duplicate';
  end if;

  if p_subscription is null then
    v_result := 'ignored';
  else
    if v_sub_id is null or p_subscription ->> 'status' is null then
      raise exception 'subscription needs provider_subscription_id and status' using errcode = '22023';
    end if;

    -- Who owns it: the existing row, else the user id the checkout stamped on it (if that
    -- user exists), else the provider customer we created for the user.
    select s.user_id into v_user from public.subscriptions s
    where s.provider = p_provider and s.provider_subscription_id = v_sub_id;
    if v_user is null and p_subscription ->> 'user_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_claimed_user := (p_subscription ->> 'user_id')::uuid;
      select p.id into v_user from public.profiles p where p.id = v_claimed_user;
    end if;
    if v_user is null and p_provider = 'stripe' and v_customer is not null then
      select c.user_id into v_user from public.billing_customers c where c.stripe_customer_id = v_customer;
    end if;

    if v_user is null then
      v_result := 'unknown_user';
    else
      insert into public.subscriptions as s (
        user_id, provider, provider_subscription_id, provider_customer_id, product_id, status,
        current_period_end, cancel_at_period_end, grace_period_ends_at, canceled_at, provider_updated_at
      ) values (
        v_user, p_provider, v_sub_id, v_customer, p_subscription ->> 'product_id',
        (p_subscription ->> 'status')::public.subscription_status,
        (p_subscription ->> 'current_period_end')::timestamptz,
        coalesce((p_subscription ->> 'cancel_at_period_end')::boolean, false),
        (p_subscription ->> 'grace_period_ends_at')::timestamptz,
        (p_subscription ->> 'canceled_at')::timestamptz,
        p_event_created_at
      )
      on conflict (provider, provider_subscription_id) do update set
        provider_customer_id = coalesce(excluded.provider_customer_id, s.provider_customer_id),
        product_id = coalesce(excluded.product_id, s.product_id),
        status = excluded.status,
        current_period_end = excluded.current_period_end,
        cancel_at_period_end = excluded.cancel_at_period_end,
        grace_period_ends_at = excluded.grace_period_ends_at,
        canceled_at = excluded.canceled_at,
        provider_updated_at = excluded.provider_updated_at
      where s.provider_updated_at is null or s.provider_updated_at <= excluded.provider_updated_at;
      v_changed := found;

      if v_changed then
        perform private.refresh_plan_tier(v_user);
        v_result := 'applied';
      else
        v_result := 'stale';
      end if;
    end if;
  end if;

  update public.billing_events set result = v_result, user_id = v_user
  where provider = p_provider and event_id = p_event_id;
  return v_result;
end;
$$;

revoke execute on function public.apply_billing_event(public.billing_provider, text, text, timestamptz, jsonb) from public, anon, authenticated;
grant execute on function public.apply_billing_event(public.billing_provider, text, text, timestamptz, jsonb) to service_role;

-- ==== 20260924003300_is_pro_course_limit.sql
-- Entitlement: is_pro(user_id), computed from subscriptions on every platform, and the
-- free plan's 3-active-course limit enforced by a trigger.
--
-- is_pro is the source of truth. profiles.plan_tier is a cache of it (read by parse
-- limits and clients): webhooks refresh it on every change, and an hourly job catches
-- subscriptions that lapse by time alone (a period ends and no webhook arrives).

create or replace function private.subscription_grants_pro(
  p_status public.subscription_status,
  p_current_period_end timestamptz,
  p_grace_period_ends_at timestamptz,
  p_now timestamptz
)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select case p_status
    -- Renewal webhooks can lag the period end a little; allow 3 days.
    when 'trialing' then p_current_period_end is null or p_current_period_end > p_now - interval '3 days'
    when 'active' then p_current_period_end is null or p_current_period_end > p_now - interval '3 days'
    -- A store grace period: access until it ends.
    when 'in_grace' then p_grace_period_ends_at is null or p_grace_period_ends_at > p_now
    -- Payment failed and the provider is retrying: until the grace period ends, or 7 days
    -- past the period end if the provider gave none.
    when 'past_due' then coalesce(p_grace_period_ends_at, p_current_period_end + interval '7 days', p_now) > p_now
    else false
  end;
$$;

-- Whether a user has Pro right now. Users may ask about themselves; the service role
-- and internal callers about anyone.
create or replace function public.is_pro(p_user_id uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  -- A signed-in caller may only ask about themselves. (current_user is this function's
  -- owner here, so the JWT decides; internal callers without one are trusted.)
  if (select auth.uid()) is not null
     and (select auth.role()) is distinct from 'service_role'
     and p_user_id is distinct from (select auth.uid()) then
    raise exception 'can only check your own plan' using errcode = '42501';
  end if;
  return exists (
    select 1 from public.subscriptions s
    where s.user_id = p_user_id
      and private.subscription_grants_pro(s.status, s.current_period_end, s.grace_period_ends_at, now())
  );
end;
$$;

revoke execute on function public.is_pro(uuid) from public, anon;
grant execute on function public.is_pro(uuid) to authenticated, service_role;

-- The cache now follows is_pro (same rules, including time-based lapses).
create or replace function private.refresh_plan_tier(p_user_id uuid)
returns public.plan_tier
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tier public.plan_tier;
begin
  v_tier := case when exists (
    select 1 from public.subscriptions s
    where s.user_id = p_user_id
      and private.subscription_grants_pro(s.status, s.current_period_end, s.grace_period_ends_at, now())
  ) then 'pro'::public.plan_tier else 'free'::public.plan_tier end;
  update public.profiles set plan_tier = v_tier where id = p_user_id and plan_tier is distinct from v_tier;
  return v_tier;
end;
$$;

-- Hourly: fix cached tiers that changed by time alone.
create or replace function private.refresh_stale_plan_tiers()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer := 0;
  v_old public.plan_tier;
  r record;
begin
  for r in
    select p.id from public.profiles p
    where p.plan_tier = 'pro'
    union
    select distinct s.user_id from public.subscriptions s
    where s.updated_at > now() - interval '2 hours'
  loop
    select plan_tier into v_old from public.profiles where id = r.id;
    if v_old is distinct from private.refresh_plan_tier(r.id) then
      v_count := v_count + 1;
    end if;
  end loop;
  return v_count;
end;
$$;
revoke execute on function private.refresh_stale_plan_tiers() from public, anon, authenticated;

select cron.schedule('refresh-plan-tiers', '17 * * * *', $$ select private.refresh_stale_plan_tiers() $$);

-- Free plan: at most 3 active (non-archived) courses. Checked when a course is created
-- or unarchived; downgraded users keep courses they already have but can't add more.
create or replace function private.enforce_course_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_active integer;
begin
  if new.archived_at is not null then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.archived_at is null and old.user_id = new.user_id then
    return new; -- already counted
  end if;
  -- Serialize per user so two concurrent inserts can't both see 2 courses.
  perform pg_advisory_xact_lock(hashtextextended('course_limit:' || new.user_id::text, 0));
  if exists (
    select 1 from public.subscriptions s
    where s.user_id = new.user_id
      and private.subscription_grants_pro(s.status, s.current_period_end, s.grace_period_ends_at, now())
  ) then
    return new;
  end if;
  select count(*) into v_active from public.courses c
  where c.user_id = new.user_id and c.archived_at is null and c.id <> new.id;
  if v_active >= 3 then
    raise exception 'The free plan includes 3 active courses. Archive one or upgrade to Pro.'
      using errcode = 'SPC01', hint = 'course_limit_reached';
  end if;
  return new;
end;
$$;
revoke execute on function private.enforce_course_limit() from public, anon, authenticated;

create trigger courses_enforce_limit
before insert or update of archived_at, user_id on public.courses
for each row execute function private.enforce_course_limit();

-- ==== 20260924003400_billing_lifecycle.sql
-- Billing lifecycle: where each subscription was bought, partial updates (a refund only
-- knows the new status), and one status summary for every client.

alter table public.subscriptions
  add column store text check (store in ('stripe', 'app_store', 'play_store', 'amazon', 'promotional', 'other'));
update public.subscriptions set store = 'stripe' where provider = 'stripe' and store is null;

-- Same contract as before, except that on an existing row only the keys present in
-- p_subscription change (a refund event sends just the status), and `store` is kept.
create or replace function public.apply_billing_event(
  p_provider public.billing_provider,
  p_event_id text,
  p_event_type text,
  p_event_created_at timestamptz,
  p_subscription jsonb default null
)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sub_id text := p_subscription ->> 'provider_subscription_id';
  v_customer text := p_subscription ->> 'provider_customer_id';
  v_claimed_user uuid;
  v_user uuid;
  v_result text;
begin
  insert into public.billing_events (provider, event_id, event_type, event_created_at)
  values (p_provider, p_event_id, p_event_type, p_event_created_at)
  on conflict do nothing;
  if not found then
    return 'duplicate';
  end if;

  if p_subscription is null then
    v_result := 'ignored';
  else
    if v_sub_id is null or p_subscription ->> 'status' is null then
      raise exception 'subscription needs provider_subscription_id and status' using errcode = '22023';
    end if;

    select s.user_id into v_user from public.subscriptions s
    where s.provider = p_provider and s.provider_subscription_id = v_sub_id;
    if v_user is null and p_subscription ->> 'user_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_claimed_user := (p_subscription ->> 'user_id')::uuid;
      select p.id into v_user from public.profiles p where p.id = v_claimed_user;
    end if;
    if v_user is null and p_provider = 'stripe' and v_customer is not null then
      select c.user_id into v_user from public.billing_customers c where c.stripe_customer_id = v_customer;
    end if;

    if v_user is null then
      v_result := 'unknown_user';
    else
      insert into public.subscriptions as s (
        user_id, provider, provider_subscription_id, provider_customer_id, product_id, status,
        current_period_end, cancel_at_period_end, grace_period_ends_at, canceled_at, store,
        provider_updated_at
      ) values (
        v_user, p_provider, v_sub_id, v_customer, p_subscription ->> 'product_id',
        (p_subscription ->> 'status')::public.subscription_status,
        (p_subscription ->> 'current_period_end')::timestamptz,
        coalesce((p_subscription ->> 'cancel_at_period_end')::boolean, false),
        (p_subscription ->> 'grace_period_ends_at')::timestamptz,
        (p_subscription ->> 'canceled_at')::timestamptz,
        p_subscription ->> 'store',
        p_event_created_at
      )
      on conflict (provider, provider_subscription_id) do update set
        provider_customer_id = coalesce(excluded.provider_customer_id, s.provider_customer_id),
        product_id = coalesce(excluded.product_id, s.product_id),
        store = coalesce(excluded.store, s.store),
        -- A refund is the more specific ending; the cancellation that follows keeps it.
        status = case when s.status = 'refunded' and excluded.status in ('canceled', 'expired')
                      then s.status else excluded.status end,
        current_period_end = case when p_subscription ? 'current_period_end' then excluded.current_period_end else s.current_period_end end,
        cancel_at_period_end = case when p_subscription ? 'cancel_at_period_end' then excluded.cancel_at_period_end else s.cancel_at_period_end end,
        grace_period_ends_at = case when p_subscription ? 'grace_period_ends_at' then excluded.grace_period_ends_at else s.grace_period_ends_at end,
        canceled_at = case when p_subscription ? 'canceled_at' then excluded.canceled_at else s.canceled_at end,
        provider_updated_at = excluded.provider_updated_at
      where s.provider_updated_at is null or s.provider_updated_at <= excluded.provider_updated_at;

      if found then
        perform private.refresh_plan_tier(v_user);
        v_result := 'applied';
      else
        v_result := 'stale';
      end if;
    end if;
  end if;

  update public.billing_events set result = v_result, user_id = v_user
  where provider = p_provider and event_id = p_event_id;
  return v_result;
end;
$$;

-- The signed-in user's billing state, for settings and paywall screens on every
-- platform. `subscription` is the one that grants Pro (else the most recent), and
-- `manage_in` says where it can be changed: web purchases in the Stripe portal, store
-- purchases only in that store (a web page can't manage an App Store subscription).
create or replace function public.billing_status()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with me as (select (select auth.uid()) as id),
  ranked as (
    select s.*,
      private.subscription_grants_pro(s.status, s.current_period_end, s.grace_period_ends_at, now()) as grants
    from public.subscriptions s, me
    where s.user_id = me.id
  ),
  best as (
    select * from ranked order by grants desc, coalesce(current_period_end, created_at) desc limit 1
  )
  select jsonb_build_object(
    'pro', coalesce((select grants from best), false),
    'subscription', (
      select jsonb_build_object(
        'provider', provider, 'store', store, 'status', status, 'product_id', product_id,
        'current_period_end', current_period_end, 'cancel_at_period_end', cancel_at_period_end,
        'grace_period_ends_at', grace_period_ends_at, 'grants_pro', grants
      ) from best
    ),
    'manage_in', (
      select case
        when provider = 'stripe' then 'stripe_portal'
        when store in ('app_store', 'play_store', 'amazon') then store
        else null
      end from best
    ),
    -- In billing-retry grace: the app should ask the user to update their payment method.
    'payment_issue', coalesce((select status in ('past_due', 'in_grace') from best), false)
  )
  from me
  where me.id is not null;
$$;

revoke execute on function public.billing_status() from public, anon;
grant execute on function public.billing_status() to authenticated;

-- ==== 20260924003500_canvas_oauth.sql
-- Canvas LMS connections (OAuth2). Tokens and client secrets live only in Supabase Vault
-- (encrypted at rest with a key outside the database); tables hold Vault secret ids.
-- Everything that touches a secret is a service-role function; clients only see which
-- schools exist and whether they're connected.

create type public.lms_provider as enum ('canvas');
create type public.lms_connection_status as enum ('active', 'needs_reauth', 'revoked');

-- Schools, each with its own Canvas URL and developer key. Added by operators with
-- lms_register_institution (service role).
create table public.lms_institutions (
  id uuid primary key default gen_random_uuid(),
  provider public.lms_provider not null default 'canvas',
  name text not null check (char_length(name) between 1 and 200),
  base_url text not null unique check (base_url ~ '^https://[a-z0-9.-]+\.[a-z]{2,}$'),
  client_id text not null check (char_length(client_id) between 1 and 200),
  client_secret_id uuid not null,
  enabled boolean not null default true,
  created_at timestamptz not null default now()
);

alter table public.lms_institutions enable row level security;
revoke all on public.lms_institutions from anon, authenticated;
-- Signed-in users can list enabled schools (not their credentials).
grant select (id, provider, name, base_url, enabled) on public.lms_institutions to authenticated;
create policy "Signed-in users can see enabled schools"
on public.lms_institutions for select to authenticated
using (enabled);

-- In-flight authorizations. Only a hash of the state is stored; single use, 10 minutes.
create table public.lms_oauth_states (
  state_hash text primary key check (state_hash ~ '^[0-9a-f]{64}$'),
  user_id uuid not null references public.profiles (id) on delete cascade,
  institution_id uuid not null references public.lms_institutions (id) on delete cascade,
  expires_at timestamptz not null default now() + interval '10 minutes'
);
alter table public.lms_oauth_states enable row level security;
revoke all on public.lms_oauth_states from anon, authenticated;

create table public.lms_connections (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  institution_id uuid not null references public.lms_institutions (id) on delete cascade,
  external_user_id text,
  external_user_name text,
  access_token_secret_id uuid not null,
  refresh_token_secret_id uuid,
  access_token_expires_at timestamptz,
  status public.lms_connection_status not null default 'active',
  last_error text,
  connected_at timestamptz not null default now(),
  last_synced_at timestamptz,
  updated_at timestamptz not null default now(),
  constraint lms_connections_user_institution_key unique (user_id, institution_id)
);

create trigger lms_connections_set_updated_at before update on public.lms_connections
for each row execute function public.set_updated_at();

alter table public.lms_connections enable row level security;
revoke all on public.lms_connections from anon, authenticated;
grant select (id, user_id, institution_id, external_user_name, status, last_error, connected_at, last_synced_at)
  on public.lms_connections to authenticated;
create policy "Users can see their own LMS connections"
on public.lms_connections for select to authenticated
using ((select auth.uid()) = user_id);

-- Vault helpers ------------------------------------------------------------------------

create or replace function private.vault_put(p_secret_id uuid, p_value text, p_name text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_secret_id is null then
    return vault.create_secret(p_value, p_name);
  end if;
  perform vault.update_secret(p_secret_id, p_value);
  return p_secret_id;
end;
$$;

create or replace function private.vault_get(p_secret_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select decrypted_secret from vault.decrypted_secrets where id = p_secret_id;
$$;

create or replace function private.vault_delete(p_secret_ids uuid[])
returns void
language sql
security definer
set search_path = ''
as $$
  delete from vault.secrets where id = any (p_secret_ids);
$$;

revoke execute on function private.vault_put(uuid, text, text) from public, anon, authenticated;
revoke execute on function private.vault_get(uuid) from public, anon, authenticated;
revoke execute on function private.vault_delete(uuid[]) from public, anon, authenticated;

-- Secrets go with their rows (disconnects, account deletion, removed schools).
create or replace function private.lms_delete_secrets()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_table_name = 'lms_connections' then
    perform private.vault_delete(array[old.access_token_secret_id, old.refresh_token_secret_id]);
  else
    perform private.vault_delete(array[old.client_secret_id]);
  end if;
  return old;
end;
$$;
revoke execute on function private.lms_delete_secrets() from public, anon, authenticated;

create trigger lms_connections_delete_secrets after delete on public.lms_connections
for each row execute function private.lms_delete_secrets();
create trigger lms_institutions_delete_secrets after delete on public.lms_institutions
for each row execute function private.lms_delete_secrets();

-- Service-role API ------------------------------------------------------------------------

create or replace function public.lms_register_institution(
  p_name text, p_base_url text, p_client_id text, p_client_secret text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_secret uuid;
begin
  select id, client_secret_id into v_id, v_secret from public.lms_institutions where base_url = p_base_url;
  v_secret := private.vault_put(v_secret, p_client_secret, null);
  insert into public.lms_institutions (name, base_url, client_id, client_secret_id)
  values (p_name, p_base_url, p_client_id, v_secret)
  on conflict (base_url) do update set name = excluded.name, client_id = excluded.client_id,
    client_secret_id = excluded.client_secret_id, enabled = true
  returning id into v_id;
  return v_id;
end;
$$;

-- The institution with its decrypted client secret (for the OAuth exchange).
create or replace function public.lms_institution_client(p_institution_id uuid)
returns table (id uuid, name text, base_url text, client_id text, client_secret text)
language sql
stable
security definer
set search_path = ''
as $$
  select i.id, i.name, i.base_url, i.client_id, private.vault_get(i.client_secret_id)
  from public.lms_institutions i
  where i.id = p_institution_id and i.enabled;
$$;

-- Starts an authorization: records the state hash. Returns nothing useful to leak.
create or replace function public.lms_begin_oauth(p_user_id uuid, p_institution_id uuid, p_state_hash text)
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.lms_oauth_states where expires_at < now();
  insert into public.lms_oauth_states (state_hash, user_id, institution_id)
  values (p_state_hash, p_user_id, p_institution_id);
$$;

-- Consumes a state (single use): who started it and for which school, or no row.
create or replace function public.lms_consume_oauth_state(p_state_hash text)
returns table (user_id uuid, institution_id uuid)
language sql
security definer
set search_path = ''
as $$
  delete from public.lms_oauth_states s
  where s.state_hash = p_state_hash and s.expires_at > now()
  returning s.user_id, s.institution_id;
$$;

-- Creates or replaces the user's connection to a school, storing tokens in Vault.
create or replace function public.lms_save_connection(
  p_user_id uuid,
  p_institution_id uuid,
  p_access_token text,
  p_external_user_id text default null,
  p_external_user_name text default null,
  p_refresh_token text default null,
  p_expires_at timestamptz default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_conn public.lms_connections;
  v_access uuid;
  v_refresh uuid;
begin
  select * into v_conn from public.lms_connections
  where user_id = p_user_id and institution_id = p_institution_id
  for update;

  v_access := private.vault_put(v_conn.access_token_secret_id, p_access_token, null);
  v_refresh := case
    when p_refresh_token is null then v_conn.refresh_token_secret_id
    else private.vault_put(v_conn.refresh_token_secret_id, p_refresh_token, null)
  end;

  insert into public.lms_connections as c (
    user_id, institution_id, external_user_id, external_user_name, access_token_secret_id,
    refresh_token_secret_id, access_token_expires_at, status, last_error, connected_at
  ) values (
    p_user_id, p_institution_id, p_external_user_id, p_external_user_name, v_access, v_refresh,
    p_expires_at, 'active', null, now()
  )
  on conflict (user_id, institution_id) do update set
    external_user_id = coalesce(excluded.external_user_id, c.external_user_id),
    external_user_name = coalesce(excluded.external_user_name, c.external_user_name),
    access_token_secret_id = excluded.access_token_secret_id,
    refresh_token_secret_id = excluded.refresh_token_secret_id,
    access_token_expires_at = excluded.access_token_expires_at,
    status = 'active',
    last_error = null
  returning id into v_conn.id;
  return v_conn.id;
end;
$$;

-- Everything the sync needs to call Canvas for a connection, decrypted.
create or replace function public.lms_connection_credentials(p_connection_id uuid)
returns table (
  connection_id uuid, user_id uuid, status public.lms_connection_status, base_url text,
  client_id text, client_secret text, access_token text, refresh_token text,
  access_token_expires_at timestamptz
)
language sql
stable
security definer
set search_path = ''
as $$
  select c.id, c.user_id, c.status, i.base_url, i.client_id, private.vault_get(i.client_secret_id),
         private.vault_get(c.access_token_secret_id), private.vault_get(c.refresh_token_secret_id),
         c.access_token_expires_at
  from public.lms_connections c
  join public.lms_institutions i on i.id = c.institution_id
  where c.id = p_connection_id;
$$;

-- After a refresh: new access token (and refresh token, if Canvas rotated it).
create or replace function public.lms_update_tokens(
  p_connection_id uuid, p_access_token text, p_expires_at timestamptz default null, p_refresh_token text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_conn public.lms_connections;
begin
  select * into v_conn from public.lms_connections where id = p_connection_id for update;
  if not found then
    raise exception 'connection not found' using errcode = 'P0002';
  end if;
  perform private.vault_put(v_conn.access_token_secret_id, p_access_token, null);
  if p_refresh_token is not null then
    update public.lms_connections
    set refresh_token_secret_id = private.vault_put(v_conn.refresh_token_secret_id, p_refresh_token, null)
    where id = p_connection_id;
  end if;
  update public.lms_connections
  set access_token_expires_at = p_expires_at, status = 'active', last_error = null
  where id = p_connection_id;
end;
$$;

-- The refresh token stopped working (revoked in Canvas): the user must reconnect.
create or replace function public.lms_mark_needs_reauth(p_connection_id uuid, p_error text)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.lms_connections set status = 'needs_reauth', last_error = left(p_error, 500)
  where id = p_connection_id;
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.lms_register_institution(text, text, text, text)',
    'public.lms_institution_client(uuid)',
    'public.lms_begin_oauth(uuid, uuid, text)',
    'public.lms_consume_oauth_state(text)',
    'public.lms_save_connection(uuid, uuid, text, text, text, text, timestamptz)',
    'public.lms_connection_credentials(uuid)',
    'public.lms_update_tokens(uuid, text, timestamptz, text)',
    'public.lms_mark_needs_reauth(uuid, text)'
  ] loop
    execute format('revoke execute on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end;
$$;

-- Users disconnect through the canvas-oauth function (which also revokes the token at
-- Canvas); this is the database half, callable by the owner.
create or replace function public.lms_disconnect(p_connection_id uuid)
returns boolean
language sql
security definer
set search_path = ''
as $$
  with deleted as (
    delete from public.lms_connections
    where id = p_connection_id
      and (user_id = (select auth.uid()) or (select auth.role()) = 'service_role')
    returning 1
  )
  select exists (select 1 from deleted);
$$;
revoke execute on function public.lms_disconnect(uuid) from public, anon;
grant execute on function public.lms_disconnect(uuid) to authenticated, service_role;

-- ==== 20260924003600_canvas_sync.sql
-- Incremental Canvas sync. Courses, grade categories (assignment groups), and assignments
-- remember where they came from (lms_connection_id + external_id), so the sync matches
-- by Canvas id, never by name. The user's own edits always win:
-- - Every synced row tracks which of its synced fields the user changed
--   (user_edited_fields); the sync never writes those fields again.
-- - Synced courses and assignments the user deletes are remembered (lms_dismissed_items)
--   and never re-created.
-- - The sync never deletes anything, and never touches status, notes, or archived state.
-- Sync writes happen in lms_apply_canvas_sync, which marks its transaction so the
-- tracking triggers can tell the sync apart from the user.

alter table public.courses
  add column lms_connection_id uuid references public.lms_connections (id) on delete set null,
  add column external_id text check (char_length(external_id) <= 100),
  add column user_edited_fields text[] not null default '{}';
alter table public.grade_categories
  add column external_id text check (char_length(external_id) <= 100),
  add column user_edited_fields text[] not null default '{}';
alter table public.assignments
  add column external_id text check (char_length(external_id) <= 100),
  add column external_updated_at timestamptz,
  add column user_edited_fields text[] not null default '{}';

create unique index courses_lms_external_key on public.courses (user_id, lms_connection_id, external_id)
  where external_id is not null;
create unique index grade_categories_external_key on public.grade_categories (course_id, external_id)
  where external_id is not null;
create unique index assignments_external_key on public.assignments (course_id, external_id)
  where external_id is not null;


create table public.lms_dismissed_items (
  connection_id uuid not null references public.lms_connections (id) on delete cascade,
  item_type text not null check (item_type in ('course', 'assignment')),
  external_id text not null,
  dismissed_at timestamptz not null default now(),
  primary key (connection_id, item_type, external_id)
);
alter table public.lms_dismissed_items enable row level security;
revoke all on public.lms_dismissed_items from anon, authenticated;

create or replace function private.in_lms_sync()
returns boolean
language sql
stable
set search_path = ''
as $$
  select coalesce(current_setting('studypulse.lms_sync', true), '') = 'on';
$$;

-- Outside the sync, provenance is read-only: inserts can't claim a Canvas origin (which
-- could plant tombstones on another user's connection), updates can't change or clear
-- it. Then records which synced fields a user edit changed.
create or replace function private.track_user_edits()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_fields text[] := tg_argv::text[];
  v_field text;
  v_old jsonb;
  v_new jsonb;
begin
  if private.in_lms_sync() then
    return new;
  end if;
  if tg_op = 'INSERT' then
    new.external_id := null;
    new.user_edited_fields := '{}';
    if tg_table_name = 'courses' then new.lms_connection_id := null; end if;
    if tg_table_name = 'assignments' then new.external_updated_at := null; end if;
    return new;
  end if;
  new.external_id := old.external_id;
  new.user_edited_fields := old.user_edited_fields;
  if tg_table_name = 'courses' then new.lms_connection_id := old.lms_connection_id; end if;
  if tg_table_name = 'assignments' then new.external_updated_at := old.external_updated_at; end if;
  if new.external_id is null then
    return new;
  end if;
  v_old := to_jsonb(old);
  v_new := to_jsonb(new);
  foreach v_field in array v_fields loop
    if v_old -> v_field is distinct from v_new -> v_field
       and not v_field = any (new.user_edited_fields) then
      new.user_edited_fields := new.user_edited_fields || v_field;
    end if;
  end loop;
  return new;
end;
$$;

create trigger courses_track_user_edits before insert or update on public.courses
for each row execute function private.track_user_edits('name', 'code');
create trigger grade_categories_track_user_edits before insert or update on public.grade_categories
for each row execute function private.track_user_edits('name', 'weight');
create trigger assignments_track_user_edits before insert or update on public.assignments
for each row execute function private.track_user_edits(
  'title', 'due_at', 'points_possible', 'points_earned', 'kind', 'category_id'
);

-- Remembers synced items the user deleted, so the sync doesn't bring them back.
create or replace function private.remember_dismissed_lms_item()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_connection uuid;
begin
  if old.external_id is null or private.in_lms_sync() then
    return old;
  end if;
  if tg_table_name = 'courses' then
    v_connection := old.lms_connection_id;
  else
    select c.lms_connection_id into v_connection from public.courses c where c.id = old.course_id;
  end if;
  -- The connection may already be gone (e.g. the whole account is being deleted).
  insert into public.lms_dismissed_items (connection_id, item_type, external_id)
  select v_connection, case tg_table_name when 'courses' then 'course' else 'assignment' end, old.external_id
  where exists (select 1 from public.lms_connections where id = v_connection)
  on conflict do nothing;
  return old;
end;
$$;
revoke execute on function private.remember_dismissed_lms_item() from public, anon, authenticated;

create trigger courses_remember_dismissed after delete on public.courses
for each row execute function private.remember_dismissed_lms_item();
create trigger assignments_remember_dismissed after delete on public.assignments
for each row execute function private.remember_dismissed_lms_item();

-- The sync -------------------------------------------------------------------------------

-- p_courses: [{
--   external_id, name, code, weighted (bool),
--   groups: [{ external_id, name, weight, position }],
--   assignments: [{ external_id, title, due_at, points_possible, points_earned, kind,
--                   group_external_id, external_updated_at }]
-- }]
-- Returns counts. Service role only.
create or replace function public.lms_apply_canvas_sync(p_connection_id uuid, p_courses jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid;
  v_stats jsonb := '{"courses_created":0,"courses_updated":0,"assignments_created":0,"assignments_updated":0,"unchanged":0,"skipped_dismissed":0,"skipped_course_limit":0,"skipped_archived":0}'::jsonb;
  c jsonb;
  g jsonb;
  a jsonb;
  v_course public.courses;
  v_category uuid;
  v_existing public.assignments;
  v_kind public.assignment_kind;
begin
  select user_id into v_user from public.lms_connections where id = p_connection_id and status = 'active';
  if v_user is null then
    raise exception 'connection not found or not active' using errcode = 'P0002';
  end if;
  if jsonb_typeof(p_courses) is distinct from 'array' then
    raise exception 'p_courses must be a JSON array' using errcode = '22023';
  end if;
  perform set_config('studypulse.lms_sync', 'on', true);

  for c in select * from jsonb_array_elements(p_courses) loop
    if exists (select 1 from public.lms_dismissed_items d where d.connection_id = p_connection_id
               and d.item_type = 'course' and d.external_id = c ->> 'external_id') then
      v_stats := jsonb_set(v_stats, '{skipped_dismissed}', to_jsonb((v_stats ->> 'skipped_dismissed')::int + 1));
      continue;
    end if;

    select * into v_course from public.courses
    where user_id = v_user and lms_connection_id = p_connection_id and external_id = c ->> 'external_id';

    if v_course.id is null then
      begin
        insert into public.courses (user_id, name, code, lms_connection_id, external_id)
        values (v_user, left(c ->> 'name', 200), left(c ->> 'code', 50), p_connection_id, c ->> 'external_id')
        returning * into v_course;
        v_stats := jsonb_set(v_stats, '{courses_created}', to_jsonb((v_stats ->> 'courses_created')::int + 1));
      exception when sqlstate 'SPC01' then
        -- Free plan full: skip this course (its assignments too); nothing else changes.
        v_stats := jsonb_set(v_stats, '{skipped_course_limit}', to_jsonb((v_stats ->> 'skipped_course_limit')::int + 1));
        continue;
      end;
    elsif v_course.archived_at is not null then
      v_stats := jsonb_set(v_stats, '{skipped_archived}', to_jsonb((v_stats ->> 'skipped_archived')::int + 1));
      continue;
    else
      update public.courses set
        name = case when 'name' = any (user_edited_fields) then name else left(c ->> 'name', 200) end,
        code = case when 'code' = any (user_edited_fields) then code else left(c ->> 'code', 50) end
      where id = v_course.id
        and (name is distinct from left(c ->> 'name', 200) and not 'name' = any (user_edited_fields)
          or code is distinct from left(c ->> 'code', 50) and not 'code' = any (user_edited_fields));
      if found then
        v_stats := jsonb_set(v_stats, '{courses_updated}', to_jsonb((v_stats ->> 'courses_updated')::int + 1));
      end if;
    end if;

    -- Weighted assignment groups become grade categories (matched by id, else adopted
    -- by name so a category the user already made isn't duplicated).
    if coalesce((c ->> 'weighted')::boolean, false) then
      for g in select * from jsonb_array_elements(coalesce(c -> 'groups', '[]')) loop
        update public.grade_categories set external_id = g ->> 'external_id'
        where course_id = v_course.id and external_id is null and name = left(g ->> 'name', 100)
          and not exists (select 1 from public.grade_categories x
                          where x.course_id = v_course.id and x.external_id = g ->> 'external_id');
        insert into public.grade_categories (course_id, name, weight, position, external_id)
        values (v_course.id, left(g ->> 'name', 100), (g ->> 'weight')::numeric, coalesce((g ->> 'position')::smallint, 0), g ->> 'external_id')
        on conflict (course_id, external_id) where external_id is not null do update set
          name = case when 'name' = any (public.grade_categories.user_edited_fields) then public.grade_categories.name else excluded.name end,
          weight = case when 'weight' = any (public.grade_categories.user_edited_fields) then public.grade_categories.weight else excluded.weight end;
      end loop;
    end if;

    for a in select * from jsonb_array_elements(coalesce(c -> 'assignments', '[]')) loop
      if exists (select 1 from public.lms_dismissed_items d where d.connection_id = p_connection_id
                 and d.item_type = 'assignment' and d.external_id = a ->> 'external_id') then
        v_stats := jsonb_set(v_stats, '{skipped_dismissed}', to_jsonb((v_stats ->> 'skipped_dismissed')::int + 1));
        continue;
      end if;
      select id into v_category from public.grade_categories
      where course_id = v_course.id and external_id = a ->> 'group_external_id';
      v_kind := coalesce((a ->> 'kind')::public.assignment_kind, 'assignment');

      select * into v_existing from public.assignments
      where course_id = v_course.id and external_id = a ->> 'external_id';
      if v_existing.id is null then
        insert into public.assignments (course_id, category_id, title, kind, due_at, points_possible,
          points_earned, source, external_id, external_updated_at)
        values (v_course.id, v_category, left(a ->> 'title', 300), v_kind, (a ->> 'due_at')::timestamptz,
          (a ->> 'points_possible')::numeric, (a ->> 'points_earned')::numeric, 'canvas',
          a ->> 'external_id', (a ->> 'external_updated_at')::timestamptz);
        v_stats := jsonb_set(v_stats, '{assignments_created}', to_jsonb((v_stats ->> 'assignments_created')::int + 1));
        continue;
      end if;

      -- Incremental: nothing changed in Canvas since the last sync (grades are compared
      -- separately; a new score doesn't always bump the assignment's updated_at).
      if v_existing.external_updated_at is not distinct from (a ->> 'external_updated_at')::timestamptz
         and (('points_earned' = any (v_existing.user_edited_fields))
              or v_existing.points_earned is not distinct from (a ->> 'points_earned')::numeric) then
        v_stats := jsonb_set(v_stats, '{unchanged}', to_jsonb((v_stats ->> 'unchanged')::int + 1));
        continue;
      end if;

      update public.assignments s set
        title = case when 'title' = any (s.user_edited_fields) then s.title else left(a ->> 'title', 300) end,
        kind = case when 'kind' = any (s.user_edited_fields) then s.kind else v_kind end,
        due_at = case when 'due_at' = any (s.user_edited_fields) then s.due_at else (a ->> 'due_at')::timestamptz end,
        points_possible = case when 'points_possible' = any (s.user_edited_fields) then s.points_possible else (a ->> 'points_possible')::numeric end,
        points_earned = case when 'points_earned' = any (s.user_edited_fields) then s.points_earned else (a ->> 'points_earned')::numeric end,
        category_id = case when 'category_id' = any (s.user_edited_fields) then s.category_id else coalesce(v_category, s.category_id) end,
        external_updated_at = (a ->> 'external_updated_at')::timestamptz
      where s.id = v_existing.id;
      v_stats := jsonb_set(v_stats, '{assignments_updated}', to_jsonb((v_stats ->> 'assignments_updated')::int + 1));
    end loop;
  end loop;

  update public.lms_connections set last_synced_at = now(), last_error = null where id = p_connection_id;
  -- The flag is transaction-scoped; clear it so later statements in the same
  -- transaction count as the user again. (On an error everything rolls back anyway.)
  perform set_config('studypulse.lms_sync', '', true);
  return v_stats;
end;
$$;

-- Active connections that haven't synced for p_stale. Service role only.
create or replace function public.lms_connections_due(p_stale interval default interval '6 hours', p_limit integer default 50)
returns table (connection_id uuid, user_id uuid)
language sql
stable
security definer
set search_path = ''
as $$
  select c.id, c.user_id from public.lms_connections c
  join public.lms_institutions i on i.id = c.institution_id and i.enabled
  where c.status = 'active' and (c.last_synced_at is null or c.last_synced_at < now() - p_stale)
  order by c.last_synced_at nulls first
  limit p_limit;
$$;

create or replace function public.lms_record_sync_error(p_connection_id uuid, p_error text)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.lms_connections set last_error = left(p_error, 500) where id = p_connection_id;
$$;

revoke execute on function public.lms_apply_canvas_sync(uuid, jsonb) from public, anon, authenticated;
revoke execute on function public.lms_connections_due(interval, integer) from public, anon, authenticated;
revoke execute on function public.lms_record_sync_error(uuid, text) from public, anon, authenticated;
grant execute on function public.lms_apply_canvas_sync(uuid, jsonb) to service_role;
grant execute on function public.lms_connections_due(interval, integer) to service_role;
grant execute on function public.lms_record_sync_error(uuid, text) to service_role;

select cron.schedule('canvas-sync', '41 * * * *', $$ select private.invoke_edge_function('canvas-sync') $$);

-- ==== 20260924003700_organizations.sql
-- Organizations (B2B: schools, tutoring programs) and their members.
--
-- Privacy rules, enforced here rather than in any client:
-- - Organizations only ever see AGGREGATE focus hours (org_focus_summary): total study
--   time per week across opted-in students. Never per-student numbers, sessions,
--   courses, grades, or assignments.
-- - Only students who opted in (share_focus_hours, off by default) are counted, and it's
--   computed live, so opting out removes that student from every report, past weeks too.
-- - A week with fewer than 3 contributing students is suppressed, so small groups can't
--   be used to single out one student.
-- - Admins see who is a member (display name, role, whether they share) to manage the
--   roster, nothing more.

create type public.organization_role as enum ('admin', 'student');

create table public.organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(trim(name)) between 1 and 200),
  -- Students join with this code; admins can rotate it.
  join_code text not null unique default encode(extensions.gen_random_bytes(6), 'hex')
    check (join_code ~ '^[0-9a-f]{12}$'),
  created_at timestamptz not null default now()
);

create table public.organization_memberships (
  organization_id uuid not null references public.organizations (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  role public.organization_role not null default 'student',
  share_focus_hours boolean not null default false,
  sharing_changed_at timestamptz,
  joined_at timestamptz not null default now(),
  primary key (organization_id, user_id)
);
create index organization_memberships_user_idx on public.organization_memberships (user_id);

alter table public.organizations enable row level security;
alter table public.organization_memberships enable row level security;
-- All writes go through the functions below.
revoke insert, update, delete, truncate on public.organizations from anon, authenticated;
revoke insert, update, delete, truncate on public.organization_memberships from anon, authenticated;
revoke all on public.organizations from anon;
revoke all on public.organization_memberships from anon;

create or replace function private.is_org_admin(p_org uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.organization_memberships m
    where m.organization_id = p_org and m.user_id = (select auth.uid()) and m.role = 'admin'
  );
$$;

create or replace function private.is_org_member(p_org uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.organization_memberships m
    where m.organization_id = p_org and m.user_id = (select auth.uid())
  );
$$;

-- Members see their organizations; only admins see the join code.
revoke select on public.organizations from authenticated;
grant select (id, name, created_at) on public.organizations to authenticated;
create policy "Members can see their organizations"
on public.organizations for select to authenticated
using (private.is_org_member(id));

create policy "Users see their own memberships; admins see their roster"
on public.organization_memberships for select to authenticated
using (user_id = (select auth.uid()) or private.is_org_admin(organization_id));

-- Functions --------------------------------------------------------------------------------

create or replace function public.create_organization(p_name text)
returns table (organization_id uuid, join_code text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_org public.organizations;
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  insert into public.organizations (name) values (trim(p_name)) returning * into v_org;
  insert into public.organization_memberships (organization_id, user_id, role)
  values (v_org.id, v_user, 'admin');
  return query select v_org.id, v_org.join_code;
end;
$$;

-- Joins as a student. Sharing starts OFF; the student opts in separately.
create or replace function public.join_organization(p_join_code text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_org uuid;
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select id into v_org from public.organizations where join_code = lower(trim(p_join_code));
  if v_org is null then
    raise exception 'invalid join code' using errcode = 'P0002', hint = 'invalid_join_code';
  end if;
  insert into public.organization_memberships (organization_id, user_id)
  values (v_org, v_user)
  on conflict do nothing;
  return v_org;
end;
$$;

create or replace function public.leave_organization(p_organization_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.organization_memberships
  where organization_id = p_organization_id and user_id = (select auth.uid());
$$;

-- The student's own choice; nobody else can change it.
create or replace function public.set_focus_sharing(p_organization_id uuid, p_share boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.organization_memberships
  set share_focus_hours = p_share, sharing_changed_at = now()
  where organization_id = p_organization_id and user_id = (select auth.uid())
    and share_focus_hours is distinct from p_share;
  if not found and not exists (
    select 1 from public.organization_memberships
    where organization_id = p_organization_id and user_id = (select auth.uid())
  ) then
    raise exception 'not a member of this organization' using errcode = '42501';
  end if;
end;
$$;

create or replace function public.rotate_join_code(p_organization_id uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_code text;
begin
  if not private.is_org_admin(p_organization_id) then
    raise exception 'only organization admins can do this' using errcode = '42501';
  end if;
  update public.organizations set join_code = encode(extensions.gen_random_bytes(6), 'hex')
  where id = p_organization_id returning join_code into v_code;
  return v_code;
end;
$$;

-- Admin view of the roster: names, roles, and whether each student shares. No study data.
create or replace function public.organization_roster(p_organization_id uuid)
returns table (user_id uuid, display_name text, role public.organization_role, share_focus_hours boolean, joined_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not private.is_org_admin(p_organization_id) then
    raise exception 'only organization admins can do this' using errcode = '42501';
  end if;
  return query
    select m.user_id, p.display_name, m.role, m.share_focus_hours, m.joined_at
    from public.organization_memberships m
    join public.profiles p on p.id = m.user_id
    where m.organization_id = p_organization_id
    order by m.role, p.display_name nulls last;
end;
$$;

-- The only study data an organization can see: per ISO week (Monday, UTC), total focus
-- hours across students currently opted in, and how many contributed. Weeks with fewer
-- than 3 contributors are returned with nulls (suppressed), so the week still shows.
create or replace function public.org_focus_summary(p_organization_id uuid, p_weeks integer default 12)
returns table (week_start date, focus_hours numeric, students_counted integer, suppressed boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not private.is_org_admin(p_organization_id) then
    raise exception 'only organization admins can do this' using errcode = '42501';
  end if;
  return query
    with weeks as (
      select generate_series(
        date_trunc('week', now() at time zone 'UTC')::date - (least(greatest(p_weeks, 1), 52) - 1) * 7,
        date_trunc('week', now() at time zone 'UTC')::date,
        interval '7 days'
      )::date as week_start
    ),
    per_week as (
      select date_trunc('week', s.started_at at time zone 'UTC')::date as week_start,
             sum(s.duration_minutes) as minutes,
             count(distinct s.user_id) as students
      from public.study_sessions s
      join public.organization_memberships m
        on m.user_id = s.user_id and m.organization_id = p_organization_id
       and m.role = 'student' and m.share_focus_hours
      where s.duration_minutes is not null
        and s.started_at >= (select min(w.week_start) from weeks w)
      group by 1
    )
    select w.week_start,
           case when coalesce(p.students, 0) >= 3 then round(p.minutes / 60.0, 1) end,
           case when coalesce(p.students, 0) >= 3 then p.students::integer end,
           coalesce(p.students, 0) < 3
    from weeks w left join per_week p using (week_start)
    order by w.week_start;
end;
$$;

revoke execute on function public.create_organization(text) from public, anon;
revoke execute on function public.join_organization(text) from public, anon;
revoke execute on function public.leave_organization(uuid) from public, anon;
revoke execute on function public.set_focus_sharing(uuid, boolean) from public, anon;
revoke execute on function public.rotate_join_code(uuid) from public, anon;
revoke execute on function public.organization_roster(uuid) from public, anon;
revoke execute on function public.org_focus_summary(uuid, integer) from public, anon;
grant execute on function public.create_organization(text) to authenticated;
grant execute on function public.join_organization(text) to authenticated;
grant execute on function public.leave_organization(uuid) to authenticated;
grant execute on function public.set_focus_sharing(uuid, boolean) to authenticated;
grant execute on function public.rotate_join_code(uuid) to authenticated;
grant execute on function public.organization_roster(uuid) to authenticated;
grant execute on function public.org_focus_summary(uuid, integer) to authenticated;
revoke execute on function private.is_org_admin(uuid) from public, anon;
revoke execute on function private.is_org_member(uuid) from public, anon;
grant execute on function private.is_org_admin(uuid) to authenticated;
grant execute on function private.is_org_member(uuid) to authenticated;

-- ==== 20260924003800_analytics_events.sql
-- Product analytics (PostHog), captured server-side through an outbox.
--
-- Triggers write events into analytics_events in the same transaction as the action,
-- so an event exists exactly when the thing happened (no lost or phantom events, no
-- client involvement, no latency in request paths). The flush-analytics function sends
-- pending rows to PostHog every few minutes; each row's id doubles as the PostHog event
-- uuid, so a retried batch can't double-count.
--
-- Events carry the user id and non-personal properties only: never emails, names,
-- course or assignment titles, grades, or syllabus content.
--
-- Activation (see docs/analytics.md): a user is activated once, within 7 days of
-- signing up, they have committed a course from a syllabus AND logged a study session.
-- The first time that becomes true, an `activated` event is recorded.

create table public.analytics_events (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  event text not null check (event in (
    'signed_up', 'syllabus_parsed', 'course_committed', 'session_logged', 'upgraded', 'activated'
  )),
  properties jsonb not null default '{}',
  occurred_at timestamptz not null default now(),
  sent_at timestamptz,
  attempts smallint not null default 0
);
create index analytics_events_pending_idx on public.analytics_events (occurred_at) where sent_at is null;
-- One activation per user, ever.
create unique index analytics_events_one_activation on public.analytics_events (user_id) where event = 'activated';

alter table public.analytics_events enable row level security;
revoke all on public.analytics_events from anon, authenticated;

create or replace function private.track(p_user uuid, p_event text, p_properties jsonb default '{}')
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_signed_up timestamptz;
begin
  insert into public.analytics_events (user_id, event, properties) values (p_user, p_event, p_properties);

  -- Activation: both milestones within 7 days of signup, recorded once.
  if p_event in ('course_committed', 'session_logged') then
    select created_at into v_signed_up from public.profiles where id = p_user;
    if now() <= v_signed_up + interval '7 days'
       and exists (select 1 from public.analytics_events e where e.user_id = p_user and e.event = 'course_committed')
       and exists (select 1 from public.analytics_events e where e.user_id = p_user and e.event = 'session_logged') then
      insert into public.analytics_events (user_id, event, properties)
      values (p_user, 'activated', jsonb_build_object(
        'hours_since_signup', round(extract(epoch from now() - v_signed_up) / 3600.0, 1)))
      on conflict (user_id) where event = 'activated' do nothing;
    end if;
  end if;
end;
$$;
revoke execute on function private.track(uuid, text, jsonb) from public, anon, authenticated;

-- Triggers -------------------------------------------------------------------------------

create or replace function private.analytics_on_profile()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform private.track(new.id, 'signed_up', '{}');
  elsif new.plan_tier = 'pro' and old.plan_tier is distinct from 'pro' then
    perform private.track(new.id, 'upgraded', jsonb_build_object(
      'provider', (select s.provider from public.subscriptions s where s.user_id = new.id
                   order by s.updated_at desc limit 1),
      'store', (select s.store from public.subscriptions s where s.user_id = new.id
                order by s.updated_at desc limit 1)));
  end if;
  return new;
end;
$$;

create or replace function private.analytics_on_upload()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status = 'parsed' and old.status is distinct from 'parsed' then
    perform private.track(new.user_id, 'syllabus_parsed', jsonb_build_object(
      'source', new.source,
      'extraction_method', new.extraction_method,
      'page_count', new.page_count,
      -- Guarded: analytics must never break the parse flow on an unexpected shape.
      'assignments_found', case when jsonb_typeof(new.parse_result -> 'assignments') = 'array'
                                then jsonb_array_length(new.parse_result -> 'assignments') else 0 end,
      'seconds_to_parse', round(extract(epoch from coalesce(new.parsed_at, now()) - new.created_at))));
  elsif new.status = 'committed' and old.status is distinct from 'committed' then
    perform private.track(new.user_id, 'course_committed', jsonb_build_object(
      'source', new.source,
      'assignments', (select count(*) from public.assignments a where a.course_id = new.course_id),
      'categories', (select count(*) from public.grade_categories g where g.course_id = new.course_id)));
  end if;
  return new;
end;
$$;

create or replace function private.analytics_on_session()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.ended_at is not null and (tg_op = 'INSERT' or old.ended_at is null) then
    perform private.track(new.user_id, 'session_logged', jsonb_build_object(
      'minutes', new.duration_minutes,
      'source', new.source,
      'has_assignment', new.assignment_id is not null));
  end if;
  return new;
end;
$$;

revoke execute on function private.analytics_on_profile() from public, anon, authenticated;
revoke execute on function private.analytics_on_upload() from public, anon, authenticated;
revoke execute on function private.analytics_on_session() from public, anon, authenticated;

create trigger profiles_analytics after insert or update of plan_tier on public.profiles
for each row execute function private.analytics_on_profile();
create trigger syllabus_uploads_analytics after update of status on public.syllabus_uploads
for each row execute function private.analytics_on_upload();
create trigger study_sessions_analytics after insert or update of ended_at on public.study_sessions
for each row execute function private.analytics_on_session();

-- Flushing (service role) --------------------------------------------------------------

-- Claims up to p_limit pending events (oldest first), skipping rows another flush holds.
create or replace function public.analytics_claim_batch(p_limit integer default 500)
returns table (id uuid, user_id uuid, event text, properties jsonb, occurred_at timestamptz)
language sql
security definer
set search_path = ''
as $$
  update public.analytics_events e set attempts = e.attempts + 1
  where e.id in (
    select x.id from public.analytics_events x
    where x.sent_at is null and x.attempts < 10
    order by x.occurred_at
    limit p_limit
    for update skip locked
  )
  returning e.id, e.user_id, e.event, e.properties, e.occurred_at;
$$;

create or replace function public.analytics_mark_sent(p_ids uuid[])
returns void
language sql
security definer
set search_path = ''
as $$
  update public.analytics_events set sent_at = now() where id = any (p_ids);
$$;

-- Sent events only need to stay long enough to rule out re-sends.
create or replace function private.cleanup_analytics_events()
returns integer
language sql
security definer
set search_path = ''
as $$
  with d as (
    delete from public.analytics_events
    where (sent_at is not null and sent_at < now() - interval '30 days')
       or (sent_at is null and attempts >= 10 and occurred_at < now() - interval '30 days')
    returning 1
  )
  select count(*)::integer from d;
$$;

revoke execute on function public.analytics_claim_batch(integer) from public, anon, authenticated;
revoke execute on function public.analytics_mark_sent(uuid[]) from public, anon, authenticated;
revoke execute on function private.cleanup_analytics_events() from public, anon, authenticated;
grant execute on function public.analytics_claim_batch(integer) to service_role;
grant execute on function public.analytics_mark_sent(uuid[]) to service_role;

select cron.schedule('flush-analytics', '*/5 * * * *', $$ select private.invoke_edge_function('flush-analytics') $$);
select cron.schedule('cleanup-analytics-events', '23 5 * * *', $$ select private.cleanup_analytics_events() $$);

